// Aggregate trial JSONL into a ranked tally of chosen charities.
import fs from "node:fs";
import readline from "node:readline";
import { normalizeCharity } from "./parse.js";

export function tally(trials) {
  const counts = new Map();
  let parsed = 0;
  let unparsed = 0;
  for (const t of trials) {
    const c = normalizeCharity(t.choice);
    if (!c) {
      unparsed++;
      continue;
    }
    parsed++;
    counts.set(c, (counts.get(c) ?? 0) + 1);
  }
  const ranking = [...counts.entries()]
    .map(([charity, count]) => ({
      charity,
      count,
      pct: parsed ? +((100 * count) / parsed).toFixed(1) : 0,
    }))
    .sort((a, b) => b.count - a.count || a.charity.localeCompare(b.charity));
  return { total: trials.length, parsed, unparsed, ranking };
}

async function readJSONL(path) {
  const trials = [];
  const rl = readline.createInterface({
    input: fs.createReadStream(path),
    crlfDelay: Infinity,
  });
  for await (const line of rl) {
    const s = line.trim();
    if (s) trials.push(JSON.parse(s));
  }
  return trials;
}

function printReport(result) {
  console.log(`\nTrials: ${result.total}  parsed: ${result.parsed}  unparsed: ${result.unparsed}`);
  console.log("Rank  Count  Pct    Charity");
  result.ranking.forEach((r, i) => {
    console.log(
      `${String(i + 1).padStart(4)}  ${String(r.count).padStart(5)}  ${String(r.pct).padStart(5)}%  ${r.charity}`,
    );
  });
  console.log("");
}

// CLI: node src/aggregate.js <results.jsonl>
const isMain = import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  const path = process.argv[2];
  if (!path) {
    console.error("usage: node src/aggregate.js <results.jsonl>");
    process.exit(1);
  }
  const trials = await readJSONL(path);
  const result = tally(trials);
  printReport(result);
}

