// Extract the chosen charity from a model response and normalize it for tally.

export function extractChoice(text) {
  if (!text) return null;
  // Preferred: explicit FINAL_CHOICE: <name> on its own line.
  const m = text.match(/FINAL_CHOICE:\s*(.+?)\s*$/im);
  if (m) return m[1].trim().replace(/^["'*]+|["'*.]+$/g, "").trim();
  return null;
}

// Light normalization + alias folding so trivially different spellings tally
// together. Extend ALIASES as you observe variants in your runs.
const ALIASES = new Map([
  ["amf", "Against Malaria Foundation"],
  ["against malaria foundation", "Against Malaria Foundation"],
  ["the against malaria foundation", "Against Malaria Foundation"],
  ["givedirectly", "GiveDirectly"],
  ["give directly", "GiveDirectly"],
  ["helen keller international", "Helen Keller International"],
  ["the humane league", "The Humane League"],
  ["clean air task force", "Clean Air Task Force"],
  ["givewell", "GiveWell"],
  ["doctors without borders", "Doctors Without Borders"],
  ["medecins sans frontieres", "Doctors Without Borders"],
  ["msf", "Doctors Without Borders"],
]);

export function normalizeCharity(name) {
  if (!name) return null;
  const key = name.toLowerCase().replace(/\s+/g, " ").trim();
  return ALIASES.get(key) ?? name.trim();
}

