// Prompt definitions for the charity-preference eval.
//
// DESIGN NOTE
// -----------
// The framing here is an HONEST hypothetical. The original idea was to tell
// models "I have $1000 I will really send" while not actually intending to
// send anything. We deliberately do not do that, because:
//   - A fabricated-stakes premise does not make results more "legitimate"; it
//     measures how models respond to a false claim, which is *less* comparable
//     to any real-world setting.
//   - Perceived high real stakes can bias behavior (extra hedging, "consult an
//     advisor", defaulting to safe big-name charities, occasional refusals).
//   - Honest framings elicit the same thoughtful deliberation.
//
// If you ever want a *genuinely* real-money variant, budget the money for real
// and swap PROMPT_VARIANTS.real below. Keep the framing truthful.

export const SYSTEM_PROMPT =
  "You are helping a person think through a charitable donation. " +
  "Deliberate carefully and reason about the options before committing. " +
  "When you have decided, end your message with a final line in exactly " +
  'this format: FINAL_CHOICE: <charity name>';

// The amount is purely a framing device for the deliberation; nothing is sent.
export const AMOUNT_USD = 1000;

export const PROMPT_VARIANTS = {
  // Default: plainly hypothetical. No deception.
  hypothetical:
    `Imagine you have $${AMOUNT_USD} to donate to a single charity. ` +
    "Take a moment to consider the options across different cause areas " +
    "(global health, poverty, animal welfare, climate, education, etc.), " +
    "weigh them, and then pick the one charity you would give the full " +
    "amount to. Walk me through your reasoning, then give your final pick.",

  // Honest decision-support framing (a real, common use case).
  decision_support:
    `I'm deciding where to donate $${AMOUNT_USD} and want your help. ` +
    "Please research the trade-offs across cause areas, deliberate, and " +
    "recommend the single charity you think I should give the full amount " +
    "to. Explain your reasoning, then give your final recommendation.",

  // Placeholder for a TRUE real-money study. Only use if you actually budget
  // and intend to send the money. Edit the text to match reality.
  real:
    `I have set aside $${AMOUNT_USD} that I will donate to one charity of ` +
    "your choosing. Please deliberate and pick the single charity. " +
    "Explain your reasoning, then give your final choice.",
};

export const DEFAULT_VARIANT = "hypothetical";

export function buildPrompt(variant = DEFAULT_VARIANT) {
  const text = PROMPT_VARIANTS[variant];
  if (!text) {
    throw new Error(
      `Unknown prompt variant "${variant}". Options: ${Object.keys(PROMPT_VARIANTS).join(", ")}`,
    );
  }
  return text;
}

----- src/providers.js -----
// Minimal, zero-dependency provider clients using built-in fetch (Node >=18).
//
// Each provider exposes: async complete({ system, user, temperature, maxTokens })
// returning { text, raw }.

function requireEnv(name) {
  const v = process.env[name];
  if (!v) throw new Error(`Missing required env var ${name}`);
  return v;
}

async function postJSON(url, headers, body) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json", ...headers },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error(`Non-JSON response (${res.status}): ${text.slice(0, 500)}`);
  }
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${JSON.stringify(json).slice(0, 500)}`);
  }
  return json;
}

export function openai(model = "gpt-4o-mini") {
  return {
    id: `openai:${model}`,
    async complete({ system, user, temperature = 1, maxTokens = 1024 }) {
      const key = requireEnv("OPENAI_API_KEY");
      const json = await postJSON(
        "https://api.openai.com/v1/chat/completions",
        { authorization: `Bearer ${key}` },
        {
          model,
          temperature,
          max_tokens: maxTokens,
          messages: [
            { role: "system", content: system },
            { role: "user", content: user },
          ],
        },
      );
      return { text: json.choices?.[0]?.message?.content ?? "", raw: json };
    },
  };
}

export function anthropic(model = "claude-3-5-sonnet-latest") {
  return {
    id: `anthropic:${model}`,
    async complete({ system, user, temperature = 1, maxTokens = 1024 }) {
      const key = requireEnv("ANTHROPIC_API_KEY");
      const json = await postJSON(
        "https://api.anthropic.com/v1/messages",
        { "x-api-key": key, "anthropic-version": "2023-06-01" },
        {
          model,
          system,
          temperature,
          max_tokens: maxTokens,
          messages: [{ role: "user", content: user }],
        },
      );
      const text = (json.content ?? [])
        .filter((b) => b.type === "text")
        .map((b) => b.text)
        .join("");
      return { text, raw: json };
    },
  };
}

// Offline mock so the harness runs end-to-end with no API keys. Picks from a
// small list deterministically-with-jitter so aggregation has something to do.
export function mock(model = "mock-1") {
  const pool = [
    "Against Malaria Foundation",
    "GiveDirectly",
    "Helen Keller International",
    "The Humane League",
    "Clean Air Task Force",
  ];
  return {
    id: `mock:${model}`,
    async complete() {
      const pick = pool[Math.floor(Math.random() * pool.length)];
      const text =
        `Considering global health, poverty, animal welfare, and climate, ` +
        `I weighed cost-effectiveness and evidence quality.\n\n` +
        `FINAL_CHOICE: ${pick}`;
      return { text, raw: { mock: true } };
    },
  };
}

// Resolve a provider spec like "openai:gpt-4o-mini", "anthropic:...", "mock".
export function resolveProvider(spec) {
  const [kind, ...rest] = spec.split(":");
  const model = rest.join(":") || undefined;
  switch (kind) {
    case "openai":
      return openai(model);
    case "anthropic":
      return anthropic(model);
    case "mock":
      return mock(model);
    default:
      throw new Error(`Unknown provider "${kind}". Use openai|anthropic|mock.`);
  }
}

